import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l3_p35_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor last_timestep_linear_cuda(
    torch::Tensor out,
    torch::Tensor weight,
    torch::Tensor bias
);

torch::Tensor last_timestep_linear(
    torch::Tensor out,
    torch::Tensor weight,
    torch::Tensor bias
) {
    TORCH_CHECK(out.is_cuda(), "out must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    return last_timestep_linear_cuda(out, weight, bias);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("last_timestep_linear", &last_timestep_linear, "Fuse last-timestep gather with linear projection (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void last_timestep_linear_kernel(
    const float* __restrict__ out_data,
    const float* __restrict__ weight_data,
    const float* __restrict__ bias_data,
    float* __restrict__ result_data,
    int B, int S, int H, int O,
    int64_t stride_b, int64_t stride_s, int64_t stride_h
) {
    int b = blockIdx.x;
    int o = blockIdx.y;
    int tid = threadIdx.x;

    const float* last_t = out_data + (int64_t)b * stride_b + (int64_t)(S - 1) * stride_s;
    const float* w_row = weight_data + o * H;

    float acc = 0.0f;
    for (int h = tid; h < H; h += blockDim.x) {
        acc += last_t[(int64_t)h * stride_h] * w_row[h];
    }

    for (int offset = 16; offset > 0; offset >>= 1) {
        acc += __shfl_down_sync(0xffffffff, acc, offset);
    }

    if (tid == 0) {
        result_data[b * O + o] = acc + bias_data[o];
    }
}

torch::Tensor last_timestep_linear_cuda(
    torch::Tensor out,
    torch::Tensor weight,
    torch::Tensor bias
) {
    TORCH_CHECK(out.dim() == 3, "out must be 3D [B, S, H]");
    TORCH_CHECK(weight.dim() == 2, "weight must be 2D [O, H]");
    TORCH_CHECK(bias.dim() == 1, "bias must be 1D [O]");

    int B = out.size(0);
    int S = out.size(1);
    int H = out.size(2);
    int O = weight.size(0);

    TORCH_CHECK(weight.size(1) == H, "weight dim 1 must match hidden size");
    TORCH_CHECK(bias.size(0) == O, "bias size must match output size");

    auto weight_c = weight.contiguous();
    auto bias_c = bias.contiguous();

    auto result = torch::empty({B, O}, out.options());

    dim3 grid(B, O);
    dim3 block(32);

    last_timestep_linear_kernel<<<grid, block>>>(
        out.data_ptr<float>(),
        weight_c.data_ptr<float>(),
        bias_c.data_ptr<float>(),
        result.data_ptr<float>(),
        B, S, H, O,
        out.stride(0), out.stride(1), out.stride(2)
    );

    return result;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers, output_size, dropout=0.0):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initialize the LSTM model.

                :param input_size: The number of expected features in the input `x`
                :param hidden_size: The number of features in the hidden state `h`
                :param num_layers: Number of recurrent layers
                :param output_size: The number of output features
                :param dropout: If non-zero, introduces a Dropout layer on the outputs of each LSTM layer except the last layer
                """
        self.hidden_size = hidden_size
        self.num_layers = num_layers
        self.lstm = nn.LSTM(input_size, hidden_size, num_layers,
                                    batch_first=True, dropout=dropout, bidirectional=False)
        self.fc = nn.Linear(hidden_size, output_size)
        # <<<END_IMPROVE>>>

    def forward(self, x, h0=None, c0=None):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Forward pass through the LSTM model.

                :param x: The input tensor, shape (batch_size, sequence_length, input_size)
                :param h0: Optional initial hidden state (num_layers, batch_size, hidden_size)
                :param c0: Optional initial cell state (num_layers, batch_size, hidden_size)
                :return: The output tensor, shape (batch_size, output_size)
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        batch_size = x.size(0)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        if h0 is None:
                    h0 = torch.randn(self.num_layers, batch_size, self.hidden_size, device=x.device)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        if c0 is None:
                    c0 = torch.randn(self.num_layers, batch_size, self.hidden_size, device=x.device)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        out, _ = self.lstm(x, (h0, c0))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        if out.is_cuda and out.dtype == torch.float32 and self.fc.weight.dtype == torch.float32 and self.fc.bias is not None:
            out = _stark_get_extension().last_timestep_linear(out, self.fc.weight, self.fc.bias)
        else:
            out = self.fc(out[:, -1, :])
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_7>>>
        return out
        # <<<END_IMPROVE>>>

